import java.util.*;

class Solution {
    public List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(nums, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> answer) {
        answer.add(new ArrayList<>(path));
        for (int i = start; i < nums.length; i++) {
            if (i > start && nums[i] == nums[i - 1]) {
                continue;
            }
            path.add(nums[i]);
            backtrack(nums, i + 1, path, answer);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> answer = new ArrayList<>();
        dfs(nums, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void dfs(int[] nums, int index, List<Integer> path, List<List<Integer>> answer) {
        if (index == nums.length) {
            answer.add(new ArrayList<>(path));
            return;
        }

        int next = index + 1;
        while (next < nums.length && nums[next] == nums[index]) {
            next++;
        }

        dfs(nums, next, path, answer);
        int copies = next - index;
        for (int used = 1; used <= copies; used++) {
            path.add(nums[index]);
            dfs(nums, next, path, answer);
        }
        for (int used = 1; used <= copies; used++) {
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> answer = new ArrayList<>();
        answer.add(new ArrayList<>());
        int previousStart = 0;

        for (int i = 0; i < nums.length; i++) {
            int start = (i > 0 && nums[i] == nums[i - 1]) ? previousStart : 0;
            int end = answer.size();
            for (int j = start; j < end; j++) {
                List<Integer> next = new ArrayList<>(answer.get(j));
                next.add(nums[i]);
                answer.add(next);
            }
            previousStart = end;
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> answer = new ArrayList<>();
        int n = nums.length;
        int totalMasks = 1 << n;

        for (int mask = 0; mask < totalMasks; mask++) {
            if (!isCanonical(nums, mask)) {
                continue;
            }
            List<Integer> subset = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    subset.add(nums[i]);
                }
            }
            answer.add(subset);
        }
        return answer;
    }

    private boolean isCanonical(int[] nums, int mask) {
        for (int i = 1; i < nums.length; i++) {
            boolean choseCurrent = (mask & (1 << i)) != 0;
            boolean chosePrevious = (mask & (1 << (i - 1))) != 0;
            if (nums[i] == nums[i - 1] && choseCurrent && !chosePrevious) {
                return false;
            }
        }
        return true;
    }
}
